import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"法律条文索引","description":"","frontmatter":{},"headers":[],"relativePath":"ja/0092-法律条文索引.md","filePath":"ja/0092-法律条文索引.md"}'),h={name:"ja/0092-法律条文索引.md"};function o(l,t,i,b,n,_){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="法律条文索引" tabindex="-1">法律条文索引 <a class="header-anchor" href="#法律条文索引" aria-label="Permalink to &quot;法律条文索引&quot;">​</a></h1><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>文書番号</td><td>92</td></tr><tr><td>モジュール</td><td>付録及び参考資料</td></tr><tr><td>キーワード</td><td>法律索引、共生憲法、労働法、消費者保護法、付随法</td></tr></tbody></table><h2 id="_1-索引の説明" tabindex="-1">1. 索引の説明 <a class="header-anchor" href="#_1-索引の説明" aria-label="Permalink to &quot;1. 索引の説明&quot;">​</a></h2><p>本索引には、アンカー共生文明の現在施行されている主要な法律文書及びその核心的な条文が、法的階層と部門別に整理されている。索引の範囲には「共生憲法」「共生労働法」「消費者保護法」、及び教育、医療、住宅、環境、独占禁止の5つの付随法が含まれる。各索引エントリには、法律名、条文番号、及び条文の核心的な内容の要約が記載されている。本索引は参考ツールであり；法律条文の全文及び司法解釈については、各法律の公式文本を参照されたい。</p><h2 id="_2-共生憲法" tabindex="-1">2. 共生憲法 <a class="header-anchor" href="#_2-共生憲法" aria-label="Permalink to &quot;2. 共生憲法&quot;">​</a></h2><p>「共生憲法」はアンカー共生文明の根本法であり、最高の法的効力を有し、共生文明の正式な樹立時に制定された。</p><table tabindex="0"><thead><tr><th>条文番号</th><th>核心的な内容</th></tr></thead><tbody><tr><td>第一条</td><td>恒元宙（万霊衡锚本源宇宙）をアンカー共生文明の統治領域として確定；共生文明の根本目的は、全ての種族の共生と宇宙的次元昇華を達成することである</td></tr><tr><td>第二条</td><td>反略奪主義を文明の根本的立場として確定；いかなる形の略奪式修練及び資源略奪を禁止する</td></tr><tr><td>第三条</td><td>「運命と進化を選択する権利を全ての有情衆生に返還する」を文明の核心理念として確定</td></tr><tr><td>第四条</td><td>多労多得、自己成長、誰にでも道がある、全種族共同前進を文明の基本方針として確定</td></tr><tr><td>第五条</td><td>三百套本源修練体系の無料公開制度を確定；いかなる組織又は個人も修練体系の伝授許可を独占してはならない</td></tr><tr><td>第六条</td><td>共同生産契約メカニズムを基本的な資源配分制度として確定</td></tr><tr><td>第七条</td><td>20%活性化戦略を段階的な国家目標として確定</td></tr><tr><td>第八条</td><td>現実に基づく原則を確定；現実世界は唯一の現実世界であり、虚構設定は法的効力を有しない</td></tr><tr><td>第九条</td><td>四段階次元昇華の道を文明の長期的発展戦略として確定</td></tr><tr><td>第十条</td><td>全種族平等の原則を確定；全ての生命形態は法の下で平等である</td></tr><tr><td>第十一条</td><td>共生進化の原則を確定；個人の進化は、他の個人又は集団の進化権利を損なう代償として行われてはならない</td></tr><tr><td>第十二条</td><td>多労多得の原則を確定；資源配分は貢献を核心的な根拠とする</td></tr><tr><td>第十三条</td><td>自己成長の原則を確定；各生命の自主的な進化選択権を尊重する</td></tr><tr><td>第十四条</td><td>誰にでも道がある原則を確定；国家は各生命に基本的な進化の道と資源保障を提供する義務を有する</td></tr><tr><td>第十五条</td><td>持続可能性の原則を確定；全ての発展は宇宙本源の持続可能性を考慮しなければならない</td></tr><tr><td>第十六条-第二十五条</td><td>全ての有情衆生の基本的権利を規定：進化選択権、修練資源獲得権、平等保護権、共生参与権、文化保存権、救済及び上訴権、人身自由権、人格尊厳権、信仰自由権、表現自由権</td></tr><tr><td>第二十六条-第三十一条</td><td>全ての有情衆生の基本的義務を規定：法律遵守義務、共生秩序維持義務、労働貢献義務、環境保護義務、他人の権利尊重義務、後進修練者指導義務</td></tr><tr><td>第三十二条</td><td>アンカー評議会を最高権力機関として確定、全種族の代表が比例して構成される</td></tr><tr><td>第三十三条</td><td>共生執行委員会を最高行政機関として確定</td></tr><tr><td>第三十四条</td><td>共生裁判所を最高司法機関として確定、独立して司法権を行使する</td></tr><tr><td>第三十五条</td><td>アンカー監察委員会を独立した監察機関として確定</td></tr><tr><td>第三十六条</td><td>立法手続を規定：法律案はアンカー評議会の過半数の賛成で可決される</td></tr><tr><td>第三十七条</td><td>憲法改正手続を規定：アンカー評議会の3分の2以上の賛成で可決され、かつ国民投票の過半数の承認を得なければならない</td></tr><tr><td>第三十八条</td><td>違憲審査制度を確定；共生裁判所は憲法に違反する法律を無効と宣言する権利を有する</td></tr><tr><td>第三十九条</td><td>憲法訴訟制度を確定；全ての有情衆生は憲法に基づいて直接訴訟を提起することができる</td></tr><tr><td>第四十条</td><td>地方自治制度を規定；各星域及び各位面は憲法の枠組み内で自治を実施する</td></tr><tr><td>第四十一条</td><td>全種族共和制度を確定；全ての民族集団は共生文明内で平等であり、区域自治を実施する</td></tr><tr><td>第四十二条</td><td>共生文明の経済制度を規定：共同生産契約を基礎とし、複数の所有制経済が共同で発展する</td></tr><tr><td>第四十三条</td><td>修練資源の国家所有及び公正配分制度を規定</td></tr><tr><td>第四十四条</td><td>教育公平制度を確定、各生命の平等な教育権を保障する</td></tr><tr><td>第四十五条</td><td>全民医療保障制度を確定</td></tr><tr><td>第四十六条</td><td>住宅保障制度を確定、各生命の基本的な住宅権を保障する</td></tr><tr><td>第四十七条</td><td>位面間交流の基本原則を規定；許可なしにいかなる無許可の位面間旅行も行ってはならない</td></tr><tr><td>第四十八条</td><td>考古活動の合法的な産出は抽象的な知識と情報に限られることを規定；物質とエネルギーの持ち帰りは禁止される</td></tr><tr><td>第四十九条</td><td>時間遡及の基本原則を規定；必ず先に観測、その後に限定的干渉の原則に従わなければならない</td></tr><tr><td>第五十条</td><td>憲法解釈権は共生裁判所に属し、憲法改正権はアンカー評議会に属することを規定</td></tr></tbody></table><h2 id="_3-共生労働法" tabindex="-1">3. 共生労働法 <a class="header-anchor" href="#_3-共生労働法" aria-label="Permalink to &quot;3. 共生労働法&quot;">​</a></h2><p>「共生労働法」は労働関係を調整し、労働者の権益を保護するための基本法であり、共生憲法第四十二条を立法根拠とする。</p><table tabindex="0"><thead><tr><th>条文番号</th><th>核心的な内容</th></tr></thead><tbody><tr><td>第一条</td><td>立法目的：労働関係を調整し、労働者の合法的な権益を保護し、調和のとれた共生的な労働関係を構築すること</td></tr><tr><td>第二条</td><td>適用範囲：恒元宙内の全ての労働関係、物質的労働、修練労働及び創造的労働を含む</td></tr><tr><td>第三条</td><td>労働者の平等就業原則を確定；人種、性別、修練レベル又は出身に基づく就業差別を禁止する</td></tr><tr><td>第四条</td><td>労働者の自由な職業選択原則を確定；強制労働及び奴隷制を禁止する</td></tr><tr><td>第五条</td><td>労働契約制度を規定；労働関係を確立する際には、書面による労働契約を締結しなければならない</td></tr><tr><td>第六条</td><td>労働契約の必要条項を規定：契約期間、業務内容、労働報酬、労働時間、労働保護、社会保険</td></tr><tr><td>第七条</td><td>8時間労働制及び週44時間を超えない労働時間制を確定</td></tr><tr><td>第八条</td><td>残業制限を規定：日次残業は1時間を超えてはならず、特殊な情況では3時間を超えてはならず、月次残業は36時間を超えてはならない</td></tr><tr><td>第九条</td><td>残業賃金基準を規定：就業日の残業は1.5倍賃金、休息日の残業は2倍賃金、法定休日の残業は3倍賃金</td></tr><tr><td>第十条</td><td>最低賃金保障制度を確定；最低賃金基準は各星域が当地の情況に応じて制定する</td></tr><tr><td>第十一条</td><td>賃金支払制度を規定：賃金は月次で労働者本人に貨幣形式で支払わなければならず、無断で控除又は遅延してはならない</td></tr><tr><td>第十二条</td><td>多労多得の配分原則を確定；労働に応じた配分を主体とし、複数の配分方式が并存する配分制度を実施する</td></tr><tr><td>第十三条</td><td>労働安全衛生制度を規定；使用者は労働者に基準に適合する労働安全衛生条件を提供しなければならない</td></tr><tr><td>第十四条</td><td>特殊群体の保護を規定：未成年労働者、女性労働者、障害者労働者及び低修練労働者に対する特殊な労働保護</td></tr><tr><td>第十五条</td><td>職業訓練制度を確定；使用者は労働者に対して職業技能訓練を実施する義務を有する</td></tr><tr><td>第十六条</td><td>修練者の労働権益を規定：修練労働も本法によって保護される；修練成果の所有権は契約によって約定される</td></tr><tr><td>第十七条</td><td>労働者の社会保険制度を確定：養老保険、医療保険、失業保険、労災保険、生育保険</td></tr><tr><td>第十八条</td><td>労働者福祉制度を規定；使用者は労働者に必要な福祉待遇を提供しなければならない</td></tr><tr><td>第十九条</td><td>労働紛争処理制度を確定：協商、調停、仲裁及び訴訟の4段階処理メカニズム</td></tr><tr><td>第二十条</td><td>労働組合制度を規定；労働者は合法的な権益を維持するため、法律に基づいて労働組合を組織し参加する権利を有する</td></tr><tr><td>第二十一条</td><td>団体契約制度を規定；労働組合は従業員を代表して使用者と団体契約を締結する</td></tr><tr><td>第二十二条</td><td>使用者の規則制度は従業員代表大会又は全従業員の討論を経なければならないことを規定</td></tr><tr><td>第二十三条</td><td>労働契約解除の条件及び手続を規定</td></tr><tr><td>第二十四条</td><td>経済補償制度を規定；使用者は法律に基づいて労働契約を解除する際に経済補償を支払わなければならない</td></tr><tr><td>第二十五条</td><td>違法な労働契約解除の賠償制度を規定</td></tr><tr><td>第二十六条</td><td>労務派遣管理制度を確定、労務派遣就業を規制する</td></tr><tr><td>第二十七条</td><td>パートタイム就業の特別規則を規定</td></tr><tr><td>第二十八条</td><td>監督検査制度を規定；労働行政部門は法律に基づいて使用者の労働法律法規遵守情況に対して監督検査を行う</td></tr><tr><td>第二十九条</td><td>法的責任を規定：本法に違反した使用者は法律に基づいて行政責任、民事責任及び刑事責任を負う</td></tr><tr><td>第三十条</td><td>本法の施行日及び解釈権を規定</td></tr></tbody></table><h2 id="_4-消費者保護法" tabindex="-1">4. 消費者保護法 <a class="header-anchor" href="#_4-消費者保護法" aria-label="Permalink to &quot;4. 消費者保護法&quot;">​</a></h2><p>「消費者保護法」は消費者の合法的な権益を保護し、経営者の行動を規制するための基本法である。</p><table tabindex="0"><thead><tr><th>条文番号</th><th>核心的な内容</th></tr></thead><tbody><tr><td>第一条</td><td>立法目的：消費者の合法的な権益を保護し、社会経済秩序を維持し、共生市場経済の健全な発展を促進すること</td></tr><tr><td>第二条</td><td>適用範囲：恒元宙内で日常消費需要のために商品を購入、使用し、又はサービスを受ける消費者の権益保護</td></tr><tr><td>第三条</td><td>経営者と消費者の取引の基本原則を確定：自願、平等、公平、誠実信用</td></tr><tr><td>第四条</td><td>消費者の合法的な権益に対する国家保護原則を確定；国家は消費者が法律に基づいて権利を行使することを保障するための措置を講じる</td></tr><tr><td>第五条</td><td>消費者の9つの基本的権利を規定：安全権、知情権、自主選択権、公平交易権、賠償請求権、結社権、知識獲得権、尊重される権利、監督権</td></tr><tr><td>第六条</td><td>消費者の安全権を規定：消費者は商品を購入、使用し、サービスを受ける際に、人身及び財産安全が損なわれない権利を享有する</td></tr><tr><td>第七条</td><td>消費者の知情権を規定：消費者は購入又は使用する商品或いは受けるサービスの真実情況を知る権利を享有する</td></tr><tr><td>第八条</td><td>消費者の自主選択権を規定：消費者は自主的に商品又はサービスを選択する権利を享有する</td></tr><tr><td>第九条</td><td>消費者の公平交易権を規定：消費者は公平交易の権利を享有し、強制交易行為を拒絶する権利を有する</td></tr><tr><td>第十条</td><td>消費者の賠償請求権を規定：商品の購入、使用又はサービスの受領により人身又は財産損害を受けた消費者は、法律に基づいて賠償を得る権利を享有する</td></tr><tr><td>第十一条</td><td>経営者の基本的義務を規定：法定及び約定義務の履行、監督の受領、安全の保障、真実情報の提供、証憑の発行、品質の保障、三包の履行、不公平交易の禁止、人格侵害の禁止</td></tr><tr><td>第十二条</td><td>経営者の安全保障義務を規定：経営者は提供する商品又はサービスが人身及び財産安全保護の要求に適合することを保障しなければならない</td></tr><tr><td>第十三条</td><td>経営者の情報開示義務を規定：経営者は消費者に商品又はサービスに関する真実情報を提供しなければならず、虚偽又は誤解を招く宣伝をしてはならない</td></tr><tr><td>第十四条</td><td>修練商品及びサービスの特別規範を規定：修練方法、修練器具及びエネルギー商品の経営者は特別資質を有しなければならず、商品は安全認証に合格しなければならない</td></tr><tr><td>第十五条</td><td>格式条項の規制を規定：経営者は格式条項により消費者の権利を排除又は制限し、経営者の責任を軽減又は免除してはならない</td></tr><tr><td>第十六条</td><td>7日無理由返品制度を規定：インターネット等の遠隔方式で商品を購入した消費者は、商品受領日から7日以内に商品を返品する権利を有する</td></tr><tr><td>第十七条</td><td>三包制度を規定：経営者が提供する商品又はサービスが品質要求に適合しない場合、消費者は国家規定に基づいて修理、交換又は返品を要求することができる</td></tr><tr><td>第十八条</td><td>懲罰的賠償制度を規定：経営者が商品又はサービスの提供において欺瞞行為がある場合、消費者の要求に基づいて消費者が受けた損失の賠償を増加しなければならず、増加した賠償額は消費者が購入した商品の価格又は受けたサービスの費用の3倍としなければならない</td></tr><tr><td>第十九条</td><td>消費者組織を規定：消費者協会及びその他の消費者組織は、法律に基づいて設立された、消費者の合法的な権益を保護するために商品及びサービスに対して社会監督を行う社会組織である</td></tr><tr><td>第二十条</td><td>消費者紛争解決ルートを規定：経営者との協商和解、消費者協会の調停申請、関連行政部門への申訴、仲裁機構への仲裁申請、人民法院への訴訟提起</td></tr><tr><td>第二十一条</td><td>紛争における挙証責任の転換を規定：耐久消費財又は装飾装修等のサービスについて、消費者が受領日から6ヶ月以内に瑕疵を発見した場合、経営者が挙証責任を負う</td></tr><tr><td>第二十二条</td><td>経営者の行政責任及び刑事責任を規定</td></tr><tr><td>第二十三条</td><td>本法の施行日及び解釈権を規定</td></tr></tbody></table><h2 id="_5-五つの付随法" tabindex="-1">5. 五つの付随法 <a class="header-anchor" href="#_5-五つの付随法" aria-label="Permalink to &quot;5. 五つの付随法&quot;">​</a></h2><h3 id="_5-1-教育保障法" tabindex="-1">5.1 教育保障法 <a class="header-anchor" href="#_5-1-教育保障法" aria-label="Permalink to &quot;5.1 教育保障法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>条文番号</th><th>核心的な内容</th></tr></thead><tbody><tr><td>第一条</td><td>立法目的：全ての有情衆生の平等な教育権を保障し、共生教育体系を構築し、全種族の文化の共同発展を促進すること</td></tr><tr><td>第二条-第五条</td><td>教育公平原則、無料教育原則（基础教育段階）、教育多様性原則、教育革新原則を確定</td></tr><tr><td>第六条-第十条</td><td>就学前教育、義務教育、高等学校段階教育、高等教育、修練教育の体系構造を規定</td></tr><tr><td>第十一条-第十五条</td><td>修練教育の特別制度を規定：三百套体系の教学規範、師父制度、修練資源配分制度</td></tr><tr><td>第十六条-第二十条</td><td>教師の権利義務、教師資格制度、教師待遇保障を規定</td></tr><tr><td>第二十一条-第二十五条</td><td>教育投入保障、教育施設建設、教育信息化、特殊教育、種族間教育を規定</td></tr><tr><td>第二十六条-第三十条</td><td>教育評価制度、教育監督制度、法的責任及び付則を規定</td></tr></tbody></table><h3 id="_5-2-医療保障法" tabindex="-1">5.2 医療保障法 <a class="header-anchor" href="#_5-2-医療保障法" aria-label="Permalink to &quot;5.2 医療保障法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>条文番号</th><th>核心的な内容</th></tr></thead><tbody><tr><td>第一条</td><td>立法目的：全民医療保障体系を構築し、全ての有情衆生の健康権を保障し、全種族の全体的な健康レベルを向上させること</td></tr><tr><td>第二条-第五条</td><td>全民医療保険原則、基本医療無料原則、中西医結合原則、修練医療包含原則を確定</td></tr><tr><td>第六条-第十条</td><td>基本医療保険、重大疾病保険、医療救助、商業健康保険の多層次医療保険体系を規定</td></tr><tr><td>第十一条-第十五条</td><td>医療機関管理、医療人員制度、医療品質と安全、修練医療の特別規範を規定</td></tr><tr><td>第十六条-第二十条</td><td>薬品管理、医療機器管理、エネルギー医療製品管理、基本薬品制度を規定</td></tr><tr><td>第二十一条-第二十五条</td><td>公衆衛生体系、疾病予防制御、健康教育、種族間医療、特殊群体の医療保障を規定</td></tr><tr><td>第二十六条-第三十条</td><td>医療紛争処理、医療監督、法的責任及び付則を規定</td></tr></tbody></table><h3 id="_5-3-住宅保障法" tabindex="-1">5.3 住宅保障法 <a class="header-anchor" href="#_5-3-住宅保障法" aria-label="Permalink to &quot;5.3 住宅保障法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>条文番号</th><th>核心的な内容</th></tr></thead><tbody><tr><td>第一条</td><td>立法目的：全ての有情衆生の基本的な住宅権を保障し、多層次住宅保障体系を構築し、全ての人に住宅を持たせることを達成する</td></tr><tr><td>第二条-第五条</td><td>住宅権保障原則、住宅公平原則、租購併挙原則、持続可能住宅原則を確定</td></tr><tr><td>第六条-第十条</td><td>公共賃貸住宅、保障性賃貸住宅、共有産権住宅、商品住宅の住宅供給体系を規定</td></tr><tr><td>第十一条-第十五条</td><td>住宅積立金制度、住宅補助制度、初住宅支援政策、修練者の特別住宅政策を規定</td></tr><tr><td>第十六条-第二十条</td><td>住宅建設基準、住宅における宇宙技術の応用、グリーン建築、高齢者友好及びバリアフリー住宅を規定</td></tr><tr><td>第二十一条-第二十五条</td><td>不動産市場規制、住宅賃貸市場規制、物業サービス管理、住宅維持保障を規定</td></tr><tr><td>第二十六条-第三十条</td><td>住宅保障監督、法的責任及び付則を規定</td></tr></tbody></table><h3 id="_5-4-環境保護法" tabindex="-1">5.4 環境保護法 <a class="header-anchor" href="#_5-4-環境保護法" aria-label="Permalink to &quot;5.4 環境保護法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>条文番号</th><th>核心的な内容</th></tr></thead><tbody><tr><td>第一条</td><td>立法目的：環境を保護し改善し、汚染及びその他の公害を予防し制御し、公衆健康を保障し、宇宙生態文明建設を推進し、持続可能な発展を促進すること</td></tr><tr><td>第二条-第五条</td><td>保護優先原則、予防为主原則、総合治理原則、公衆参与原則、損害担責原則を確定</td></tr><tr><td>第六条-第十条</td><td>環境監督管理制度、環境基準制度、環境影響評価制度、環境監測制度、位面間環境管理を規定</td></tr><tr><td>第十一条-第十五条</td><td>大気汚染予防制御、水質汚染予防制御、土壌汚染予防制御、エネルギー汚染予防制御、法則汚染予防制御を規定</td></tr><tr><td>第十六条-第二十条</td><td>固体廃棄物処理、騒音汚染予防制御、放射線汚染予防制御、生態保護、生物多様性保護を規定</td></tr><tr><td>第二十一条-第二十五条</td><td>修練活動の環境影響制御、エネルギー鉱山の生態保護、位面間考古の環境要求を規定</td></tr><tr><td>第二十六条-第三十条</td><td>情報公開と公衆参与、環境公益訴訟、法的責任及び付則を規定</td></tr></tbody></table><h3 id="_5-5-独占禁止法" tabindex="-1">5.5 独占禁止法 <a class="header-anchor" href="#_5-5-独占禁止法" aria-label="Permalink to &quot;5.5 独占禁止法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>条文番号</th><th>核心的な内容</th></tr></thead><tbody><tr><td>第一条</td><td>立法目的：独占行為を予防し制止し、市場の公平競争を保護し、経済運行効率を向上させ、消費者利益及び社会公共利益を維持し、共生市場経済の健全な発展を促進すること</td></tr><tr><td>第二条-第五条</td><td>競争政策の基本的立場、公平競争審査制度、独占協定禁止、市場支配的地位の濫用禁止、経営者集中制御を確定</td></tr><tr><td>第六条-第十条</td><td>独占協定の認定と豁免、横断的独占協定、縦断的独占協定、業界協会の独占行為を規定</td></tr><tr><td>第十一条-第十五条</td><td>市場支配的地位の認定、市場支配的地位濫用行為の類型、略奪的価格設定禁止を規定</td></tr><tr><td>第十六条-第二十条</td><td>経営者集中の申告基準、審査手続、付加的制限条件、集中禁止決定を規定</td></tr><tr><td>第二十一条-第二十五条</td><td>修練体系独占の特別禁止を規定：修練方法独占禁止、修練資源独占禁止、師父ネットワーク独占禁止</td></tr><tr><td>第二十六条-第三十条</td><td>独占禁止法執行機関、調査手続、法的責任、寛大制度及び付則を規定</td></tr></tbody></table><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>法律条文索引はアンカー共生文明の法治体系の参考地図である。根本法としての共生憲法から、民生を規制する労働法と消費者保護法、そして五つの付随法まで、それらは共同で「憲法を帥とし、基本法を骨格とし、付随法を支えとする」完全な法律体系を構成する。この体系は共生文明の全ての活動が法治の軌道上で運行されることを保障し、全種族の共同前進のために堅実な制度的保障を提供する。</p><h2 id="関連文書" tabindex="-1">関連文書 <a class="header-anchor" href="#関連文書" aria-label="Permalink to &quot;関連文書&quot;">​</a></h2><ul><li>40-共生憲法総綱</li><li>41-共生労働法</li><li>48-司法体系と裁判メカニズム</li></ul>',28)])])}const u=d(h,[["render",o]]);export{c as __pageData,u as default};
